/* ---------- sidebar + account menu ---------- */
function setAccountMenu(open) {
  accountMenu.classList.toggle('is-open', open);
  accountBtn.setAttribute('aria-expanded', String(open));
}

function setMobileSidebar(open) {
  app.classList.toggle('sidebar-open', open);
  mobileSidebarBtn.setAttribute('aria-expanded', String(open));
  sidebarToggle.setAttribute('aria-expanded', String(open));
  if (!open) setAccountMenu(false);
}

function setSidebarCollapsed(collapsed) {
  app.classList.toggle('sidebar-collapsed', collapsed);
  sidebarToggle.setAttribute('aria-expanded', String(!collapsed));
  sidebarToggle.setAttribute('aria-label', collapsed ? '展开侧栏' : '收起侧栏');
  sidebarToggle.setAttribute('title', collapsed ? '展开侧栏' : '收起侧栏');
  setAccountMenu(false);
}

sidebarToggle.addEventListener('click', function () {
  if (narrowSidebar.matches) {
    setMobileSidebar(!app.classList.contains('sidebar-open'));
  } else {
    setSidebarCollapsed(!app.classList.contains('sidebar-collapsed'));
  }
});

