/* ---------- session list ---------- */
var sessions = Array.prototype.slice.call(document.querySelectorAll('.session'));

sessions.forEach(function (item) {
  var row = document.createElement('div');
  row.className = 'session-row';
  item.parentNode.insertBefore(row, item);
  row.appendChild(item);

  var more = document.createElement('button');
  more.type = 'button';
  more.className = 'session-more';
  more.title = '会话操作';
  more.setAttribute('aria-label', '会话操作');
  more.setAttribute('aria-haspopup', 'menu');
  more.setAttribute('aria-expanded', 'false');
  more.innerHTML = '<svg class="ic" aria-hidden="true"><use href="#i-more"/></svg>';
  row.appendChild(more);

  more.addEventListener('click', function (event) {
    event.stopPropagation();
    openSessionMenu(row, more);
  });
  row.addEventListener('contextmenu', function (event) {
    event.preventDefault();
    openSessionMenu(row, null, event.clientX, event.clientY);
  });
});

sessions.forEach(function (item) {
  item.addEventListener('click', function () {
    sessions.forEach(function (s) {
      s.classList.remove('is-active');
      s.removeAttribute('aria-current');
    });
    item.classList.add('is-active');
    item.setAttribute('aria-current', 'page');
    if (narrowSidebar.matches) setMobileSidebar(false);
  });
});

function openSessionMenu(row, anchor, x, y) {
  if (sessionMenu.classList.contains('is-open') && sessionMenuTarget === row) {
    closeSessionMenu();
    return;
  }
  setAccountMenu(false);
  if (sessionMenuAnchor) sessionMenuAnchor.setAttribute('aria-expanded', 'false');
  sessionMenuTarget = row;
  sessionMenuAnchor = anchor || null;
  if (sessionMenuAnchor) sessionMenuAnchor.setAttribute('aria-expanded', 'true');

  var left, top;
  if (typeof x === 'number' && typeof y === 'number') {
    left = x; top = y;
  } else {
    var rect = anchor.getBoundingClientRect();
    left = rect.right - 176;
    top = rect.bottom + 4;
  }
  left = Math.min(Math.max(8, left), window.innerWidth - 184);
  top = Math.min(Math.max(8, top), window.innerHeight - 132);
  sessionMenu.style.left = left + 'px';
  sessionMenu.style.top = top + 'px';
  sessionMenu.classList.add('is-open');
  var first = sessionMenu.querySelector('.menu-item');
  if (first) first.focus();
}

function closeSessionMenu() {
  sessionMenu.classList.remove('is-open');
  if (sessionMenuAnchor) {
    sessionMenuAnchor.setAttribute('aria-expanded', 'false');
    sessionMenuAnchor = null;
  }
  sessionMenuTarget = null;
}

function startRename(row) {
  var btn = row.querySelector('.session');
  var title = row.querySelector('.session-title');
  var more = row.querySelector('.session-more');
  if (!btn || !title || !more) return;
  var old = title.textContent;
  var input = document.createElement('input');
  input.type = 'text';
  input.className = 'session-rename';
  input.value = old;

  var exists = Array.prototype.some.call(menuWorkflowItems.querySelectorAll('[data-workflow]'), function (btn) {
    return btn.getAttribute('data-workflow') === id;
  });
  if (exists) return;
  var btn = document.createElement('button');
  btn.className = 'cm-radio';
  btn.setAttribute('data-workflow', id);
  btn.setAttribute('role', 'menuitemradio');
  btn.setAttribute('aria-checked', 'false');
  btn.innerHTML = '<span class="cm-radio-dot"></span>' +
    '<span class="cm-main">' + escComposer(wf.name) + '</span>' +
    '<span class="cm-hint">' + wf.steps.length + ' 步</span>';
  btn.addEventListener('click', function () {
    selectWorkflow(id, true);
  });
  menuWorkflowItems.appendChild(btn);
  updateComposerMenuState();
}

function updateMenuWorkflowItem(id, wf) {
  if (!menuWorkflowItems) return;
  var btn = Array.prototype.find.call(menuWorkflowItems.querySelectorAll('[data-workflow]'), function (item) {
    return item.getAttribute('data-workflow') === id;
  });
  if (!btn) return;
  var main = btn.querySelector('.cm-main');
  var hint = btn.querySelector('.cm-hint');
  if (main) main.textContent = wf.name;
  if (hint) hint.textContent = wf.steps.length + ' 步';
}

function applyWorkflowHash() {
  var raw = window.location.hash.replace(/^#/, '');
  if (!raw) return;
  var params;
  try { params = new URLSearchParams(raw); } catch (e) { return; }
  var id = params.get('workflow');
  if (!id) return;
  var name = params.get('name');
  var stepsRaw = params.get('steps');
  var incomingSteps = name && stepsRaw ? stepsRaw.split('|').filter(Boolean) : null;
  var wf = CHAT_WORKFLOWS[id];
  if (!wf) {
    if (!name || !incomingSteps || !incomingSteps.length) return;
    CHAT_WORKFLOWS[id] = { name: name, steps: incomingSteps, disabled: false };
    addCustomWorkflowMenuItem(id, CHAT_WORKFLOWS[id]);
    wf = CHAT_WORKFLOWS[id];
  } else if (name && incomingSteps && incomingSteps.length) {
    wf.name = name;
    wf.steps = incomingSteps;
    updateMenuWorkflowItem(id, wf);
  }
  if (!wf || wf.disabled) return;
  selectedWorkflow = id;
  renderComposerContext();
  showToast('已载入工作流：' + wf.name);
}

composerPlus.addEventListener('click', function () {
  if (composerMenu.hidden) openComposerMenu();
  else closeComposerMenu();
});

cmAttach.addEventListener('click', function () {
  mentionPending = false;
  closeComposerMenu();
  fileInput.click();
});

fileInput.addEventListener('change', function () {
  var names = [];
  Array.prototype.forEach.call(fileInput.files || [], function (file) {
    names.push(file.name);
  });
  fileInput.value = '';
  if (!names.length) {
    mentionPending = false;
    return;
  }
  if (mentionPending) {
    var insert = '@' + names[0] + ' ';
    var start = input.selectionStart === null ? input.value.length : input.selectionStart;
    var before = input.value.slice(0, start);
    var after = input.value.slice(start);
    var at = before.lastIndexOf('@');
    if (at !== -1) {
      input.value = before.slice(0, at) + insert + after;
      var pos = at + insert.length;
      input.setSelectionRange(pos, pos);
    } else {
      input.value += insert;
    }
    mentionPending = false;
    autoGrow();
    updateSendState();
    input.focus();
  }
  attachedFiles = attachedFiles.concat(names);
  renderComposerContext();
  showToast('已添加 ' + names.length + ' 个附件');
});

composerContext.addEventListener('click', function (event) {
  var btn = event.target.closest('[data-remove]');
  if (!btn) return;
  var kind = btn.getAttribute('data-remove');
  if (kind === 'workflow') selectedWorkflow = null;
  if (kind === 'skill') {
    var skill = btn.getAttribute('data-value');
    selectedSkills = selectedSkills.filter(function (id) { return id !== skill; });
  }
  if (kind === 'knowledge') knowledgeSelected = false;
  if (kind === 'mcp') {
    var mcp = btn.getAttribute('data-value');
    selectedMcp = selectedMcp.filter(function (id) { return id !== mcp; });
  }
  if (kind === 'file') {
    var idx = Number(btn.getAttribute('data-index'));
    attachedFiles.splice(idx, 1);
  }
  renderComposerContext();
});

document.querySelectorAll('[data-skill]').forEach(function (btn) {
  btn.addEventListener('click', function () {
    toggleSkill(btn.getAttribute('data-skill'));
  });
});

document.querySelectorAll('[data-workflow]').forEach(function (btn) {
  btn.addEventListener('click', function () {
    if (btn.disabled) return;
    selectWorkflow(btn.getAttribute('data-workflow'), true);
  });
});

document.querySelectorAll('[data-knowledge]').forEach(function (btn) {
  btn.addEventListener('click', toggleKnowledge);
});

document.querySelectorAll('[data-mcp]').forEach(function (btn) {
  btn.addEventListener('click', function () {
    toggleMcp(btn.getAttribute('data-mcp'));
  });
});

modelBtn.addEventListener('click', function () {
