    setEffort(btn.getAttribute('data-effort'));
  });
});

document.addEventListener('click', function (event) {
  if (!event.target.closest('.plus-wrap')) closeComposerMenu();
  if (!event.target.closest('.model-wrap')) closeModelMenu();
});

document.addEventListener('keydown', function (event) {
  if (event.key === 'Escape') {
    closeComposerMenu();
    closeModelMenu();
  }
});

window.addEventListener('hashchange', applyWorkflowHash);

renderComposerContext();

/* ---------- thinking + process collapse ---------- */
function updateRunViewbar() {
  if (!runViewbar) return;
  var turn = runViewbar.closest('.turn');
  if (turn) turn.classList.toggle('is-process-collapsed', runCollapsed);
  runToggle.setAttribute('aria-expanded', String(!runCollapsed));
  runToggleLabel.textContent = runCollapsed ? '展开过程' : '收起过程';
  runViewTitle.textContent = runCollapsed ? '过程已收起' : '执行过程';
  runApprovalLink.hidden = !approvalPending;
}

function setRunViewStatus(state) {
  if (!runViewStatus) return;
  if (state === 'running') {
    runViewStatus.className = 'st st-live';
    runViewStatus.innerHTML = '<span class="dot is-live"></span>运行中';
  } else if (state === 'done') {
    runViewStatus.className = 'st st-ok';
    runViewStatus.innerHTML = '<span class="dot is-ok"></span>已完成';
  } else if (state === 'rejected') {
    runViewStatus.className = 'st st-muted';
    runViewStatus.textContent = '已取消';
  } else {
    runViewStatus.className = 'st st-live';
    runViewStatus.innerHTML = '<span class="dot is-live"></span>待审批';
  }
  updateRunViewbar();
}

runToggle.addEventListener('click', function () {
  runCollapsed = !runCollapsed;
  updateRunViewbar();
});

runApprovalLink.addEventListener('click', function () {
  runCollapsed = false;
  updateRunViewbar();
  var entry = document.getElementById('approvalEntry');
  if (entry) entry.scrollIntoView({ behavior: 'smooth', block: 'center' });
  var approveBtn = approvalCard.querySelector('[data-decision="approve"]');
  if (approveBtn) setTimeout(function () { approveBtn.focus({ preventScroll: true }); }, 260);
});

thinkingToggle.addEventListener('click', function () {
  var collapsed = thinkingCard.classList.toggle('is-collapsed');
  thinkingBody.hidden = collapsed;
  thinkingToggle.setAttribute('aria-expanded', String(!collapsed));
});

updateRunViewbar();

/* ---------- composer ---------- */
function autoGrow() {
  input.style.height = 'auto';
  input.style.height = Math.min(input.scrollHeight, 168) + 'px';
}

function updateSendState() {
  var hasText = input.value.trim().length > 0;
  var canStop = runActive;
  var blocked = canStop ? false : (!hasText || approvalPending);
  sendBtn.classList.toggle('is-stop', canStop);
  sendBtn.classList.toggle('is-disabled', blocked);
  sendBtn.disabled = blocked;
  sendBtn.setAttribute('aria-label', canStop ? '停止本轮运行' : '发送消息');
  sendBtn.title = canStop
    ? '停止本轮运行'
    : (approvalPending ? '请先处理上方的发送审批' : '发送');
  if (runStatus) {
    runStatus.disabled = !approvalPending;
    runStatus.setAttribute('aria-label', runStatusText.textContent + (approvalPending ? '，点击处理' : ''));
  }
}

input.addEventListener('input', function () {
  autoGrow();
  updateSendState();
});

input.addEventListener('keydown', function (event) {
  if (event.key === '@' && !event.isComposing) {
    mentionPending = true;
    setTimeout(function () { fileInput.click(); }, 0);
  }
  if (event.key === 'Enter' && !event.shiftKey && !event.isComposing) {
    event.preventDefault();
    send();
  }
});

sendBtn.addEventListener('click', function () {
  if (runActive) {
    stopRun();
    return;
  }
  send();
});

function nowTime() {
  var d = new Date();
  return String(d.getHours()).padStart(2, '0') + ':' + String(d.getMinutes()).padStart(2, '0');
}

function makeEntry(className, who, whoSub, bodyHTML) {
  var li = document.createElement('li');
  li.className = 'entry ' + className;
  li.innerHTML =
    '<span class="node" aria-hidden="true"></span>' +
    '<div class="entry-head">' +
      '<span class="who"></span>' +
      '<span class="who-sub"></span>' +
      '<span class="spacer"></span>' +
      '<time></time>' +
    '</div>' +
    '<div class="entry-body"></div>';
  li.querySelector('.who').textContent = who;
  li.querySelector('.who-sub').textContent = whoSub;
  li.querySelector('time').textContent = nowTime();
  li.querySelector('.entry-body').innerHTML = bodyHTML;
  return li;
}

function scrollToBottom() {
  stream.scrollTop = stream.scrollHeight;
}

function send() {
  var text = input.value.trim();
  if (!text) return;
  if (approvalPending) {
    showToast('待审批中，请先处理审批或停止本轮');
    return;
  }
  if (runActive) {
    showToast('本轮正在执行，点发送按钮可停止');
    return;
  }

  var workflow = selectedWorkflow ? CHAT_WORKFLOWS[selectedWorkflow] : null;
  var contextFiles = attachedFiles.slice();
  var contextSkills = selectedSkills.slice();
  var contextMcp = selectedMcp.slice();

    var contextMcp = selectedMcp.slice();
    var contextKnowledge = knowledgeSelected;

    var turn = document.createElement('section');
    turn.className = 'turn';

    var userTurn = document.createElement('div');
    userTurn.className = 'user-turn';
    userTurn.innerHTML =
      '<div class="user-meta">' +
        '<span>你</span><span class="meta-sep">·</span>' +
        '<time></time><span class="meta-sep">·</span>' +
        '<span>Web 工作台</span>' +
      '</div>' +
      '<div class="prompt-bubble"><p></p><div class="attachments"></div></div>';
    userTurn.querySelector('time').textContent = nowTime();
    userTurn.querySelector('.prompt-bubble p').textContent = text;

    var attachHTML = '';
    contextFiles.forEach(function (name) {
      attachHTML += '<span class="attach"><svg class="ic" aria-hidden="true"><use href="#i-clip"/></svg>' + escComposer(name) + '</span>';
    });
    contextSkills.forEach(function (id) {
      attachHTML += '<span class="attach"><svg class="ic" aria-hidden="true"><use href="#i-stack"/></svg>' + escComposer(id) + '</span>';
    });
    if (contextKnowledge) {
      attachHTML += '<span class="attach"><svg class="ic" aria-hidden="true"><use href="#i-db"/></svg>support-kb</span>';
    }
    contextMcp.forEach(function (id) {
      attachHTML += '<span class="attach"><svg class="ic" aria-hidden="true"><use href="#i-stack"/></svg>' + escComposer(id) + '</span>';
    });
    var attachBox = userTurn.querySelector('.prompt-bubble .attachments');
    if (attachHTML) attachBox.innerHTML = attachHTML;
    else attachBox.remove();

    var wfLine = null;
    if (workflow) {
      userTurn.style.marginBottom = '10px';
      wfLine = document.createElement('div');
      wfLine.className = 'turn-workflow';
      wfLine.innerHTML =
        '<svg class="ic" aria-hidden="true"><use href="#i-workflow"/></svg>' +
        '<b>工作流 · ' + escComposer(workflow.name) + '</b>' +
        '<span class="turn-wf-steps">' + escComposer(workflow.steps.join(' → ')) + '</span>';
    }

    var ol = document.createElement('ol');
    ol.className = 'thread';

    var reply = makeEntry(
      'entry-assistant',
      'main-agent',
      '调度员',
      '<div class="thinking-live"><svg class="ic" aria-hidden="true"><use href="#i-spark"/></svg><span>正在思考</span><span class="thinking-dots">· · ·</span></div><div class="prose"><p class="typing" aria-label="正在生成">· · ·</p></div>'
    );
    ol.appendChild(reply);

    turn.appendChild(userTurn);
    if (wfLine) turn.appendChild(wfLine);
    turn.appendChild(ol);
    conversation.appendChild(turn);

    var replyBits = [];
    if (workflow) {
      replyBits.push('收到，我会按「' + escComposer(workflow.name) + '」的 ' + workflow.steps.length + ' 步执行，并在写操作前再次确认。');
    } else {
      replyBits.push('收到，我会把这条补充并入当前上下文，并在下一次发送前再次向你确认。');
    }
    var contextBits = [];
    if (contextSkills.length) contextBits.push(contextSkills.length + ' 个技能');
    if (contextMcp.length) contextBits.push(contextMcp.length + ' 个 MCP 服务器');
    if (contextKnowledge) contextBits.push('知识库 support-kb');
    if (contextFiles.length) contextBits.push(contextFiles.length + ' 个附件');
    if (contextBits.length) replyBits.push('已带上 ' + contextBits.join('、') + '。');
    var replyHTML = '<div class="prose"><p>' + replyBits.join(' ') + '</p></div>';

    input.value = '';
    attachedFiles = [];
    selectedSkills = [];
    selectedMcp = [];
    knowledgeSelected = false;
    selectedWorkflow = null;
    renderComposerContext();
    autoGrow();
    updateSendState();
    scrollToBottom();

    setTimeout(function () {
      reply.querySelector('.entry-body').innerHTML = replyHTML;
      scrollToBottom();
    }, 1300);
  }

  /* ---------- copy ---------- */
  function fallbackCopy(text) {
    var ta = document.createElement('textarea');
    ta.value = text;
    ta.setAttribute('readonly', '');
    ta.style.position = 'fixed';
    ta.style.opacity = '0';
    document.body.appendChild(ta);
    ta.select();
    try {
      document.execCommand('copy');
      showToast('已复制到剪贴板');
    } catch (err) {
      showToast('复制失败，请手动选择文本');
    }
    document.body.removeChild(ta);
  }

  document.querySelectorAll('.copy-btn').forEach(function (btn) {
    btn.addEventListener('click', function () {
      var text = btn.getAttribute('data-copy') || '';
      if (navigator.clipboard && window.isSecureContext) {
        navigator.clipboard.writeText(text).then(function () {
          showToast('已复制到剪贴板');
        }).catch(function () {
          fallbackCopy(text);
        });
      } else {
        fallbackCopy(text);
      }
    });
  });

  /* ---------- demo affordances ---------- */
  document.querySelectorAll('[data-demo]').forEach(function (btn) {
    btn.addEventListener('click', function () {
      showToast(btn.getAttribute('data-demo'));
      if (narrowSidebar.matches && btn.closest('.sidebar')) setMobileSidebar(false);
    });
  });

  updateSendState();
  autoGrow();
  applyWorkflowHash();
})();
</script>
</body>
</html>

var deleteSessionName = document.getElementById('deleteSessionName');
var confirmDelete = document.getElementById('confirmDelete');
var cancelDelete = document.getElementById('cancelDelete');
var sessionMenuTarget = null;
var sessionMenuAnchor = null;
var deleteSessionTarget = null;
var toastTimer = null;

/* ---------- theme ---------- */
try {
  var savedTheme = localStorage.getItem('ah-theme');
  if (savedTheme === 'dark' || savedTheme === 'light') root.dataset.theme = savedTheme;
} catch (e) {}

function showToast(text) {
  toastText.textContent = text;
  toast.classList.add('is-visible');
  clearTimeout(toastTimer);
  toastTimer = setTimeout(function () { toast.classList.remove('is-visible'); }, 2400);
}

function syncThemeControls() {
  document.querySelectorAll('[data-theme-choice]').forEach(function (btn) {
    btn.classList.toggle('is-active', btn.getAttribute('data-theme-choice') === root.dataset.theme);
  });
}

function applyTheme(theme) {
  root.dataset.theme = theme;
  try { localStorage.setItem('ah-theme', theme); } catch (e) {}
  syncThemeControls();
}

/* ---------- sidebar + account menu ---------- */
function setAccountMenu(open) {
  accountMenu.classList.toggle('is-open', open);
  accountBtn.setAttribute('aria-expanded', String(open));
}

function setMobileSidebar(open) {
  app.classList.toggle('sidebar-open', open);
  mobileSidebarBtn.setAttribute('aria-expanded', String(open));
  sidebarToggle.setAttribute('aria-expanded', String(open));
  if (!open) setAccountMenu(false);
}

function setSidebarCollapsed(collapsed) {
  app.classList.toggle('sidebar-collapsed', collapsed);
  sidebarToggle.setAttribute('aria-expanded', String(!collapsed));
  sidebarToggle.setAttribute('aria-label', collapsed ? '展开侧栏' : '收起侧栏');
  sidebarToggle.setAttribute('title', collapsed ? '展开侧栏' : '收起侧栏');
  setAccountMenu(false);
}

sidebarToggle.addEventListener('click', function () {
  if (narrowSidebar.matches) {
    setMobileSidebar(!app.classList.contains('sidebar-open'));
  } else {
    setSidebarCollapsed(!app.classList.contains('sidebar-collapsed'));
  }
});

mobileSidebarBtn.addEventListener('click', function () {
  setMobileSidebar(!app.classList.contains('sidebar-open'));
});

sidebarScrim.addEventListener('click', function () { setMobileSidebar(false); });

accountBtn.addEventListener('click', function () {
  setAccountMenu(!accountMenu.classList.contains('is-open'));
});

document.addEventListener('click', function (event) {
  if (!accountMenu.contains(event.target) && !accountBtn.contains(event.target)) {
    setAccountMenu(false);
  }
});

document.addEventListener('keydown', function (event) {
  if (event.key === 'Escape') {
    setAccountMenu(false);
    if (narrowSidebar.matches) setMobileSidebar(false);
  }
});

accountMenu.querySelectorAll('.menu-item').forEach(function (item) {
  item.addEventListener('click', function () { setAccountMenu(false); });
});

narrowSidebar.addEventListener('change', function () {
  setAccountMenu(false);
  app.classList.remove('sidebar-open');
  mobileSidebarBtn.setAttribute('aria-expanded', 'false');
  if (narrowSidebar.matches) {
    app.classList.remove('sidebar-collapsed');
    sidebarToggle.setAttribute('aria-expanded', 'false');
  } else {
    sidebarToggle.setAttribute('aria-expanded', String(!app.classList.contains('sidebar-collapsed')));
  }
});

if (narrowSidebar.matches) {
  app.classList.remove('sidebar-collapsed');
  sidebarToggle.setAttribute('aria-expanded', 'false');
}

/* ---------- pages ---------- */
function syncSettingsNav(id) {
  document.querySelectorAll('[data-scroll]').forEach(function (item) {
    item.classList.toggle('is-active', item.getAttribute('data-scroll') === id);
  });
}

function showPage(name, section) {
  if (!pageTitles[name]) name = 'agents';
  if (section && !document.getElementById(section)) section = 'settings-' + section;
  document.querySelectorAll('.page').forEach(function (page) {
    page.hidden = page.getAttribute('data-page') !== name;
  });
  document.querySelectorAll('.sb-nav-item[data-page]').forEach(function (item) {
    var active = item.getAttribute('data-page') === name;
    item.classList.toggle('is-active', active);
    if (active) item.setAttribute('aria-current', 'page');
    else item.removeAttribute('aria-current');
  });
  mobilePageTitle.textContent = pageTitles[name];
  document.title = pageTitles[name] + ' · Agent Hub';
  pageScroll.scrollTop = 0;
  try { history.replaceState(null, '', '#' + name); } catch (e) {}
  setAccountMenu(false);
  if (narrowSidebar.matches) setMobileSidebar(false);
  if (name === 'settings') syncSettingsNav(section || 'settings-account');
  if (section) {
    requestAnimationFrame(function () {
      var target = document.getElementById(section);
      if (target) target.scrollIntoView({ behavior: 'smooth', block: 'start' });
      syncSettingsNav(section);
    });
  }
}

document.querySelectorAll('.sb-nav-item[data-page], .account-menu .menu-item[data-page]').forEach(function (item) {
  item.addEventListener('click', function () {
    showPage(item.getAttribute('data-page'), item.getAttribute('data-section'));
  });
});

document.querySelectorAll('[data-scroll]').forEach(function (item) {
  item.addEventListener('click', function () {
    var id = item.getAttribute('data-scroll');
    var target = document.getElementById(id);
    if (target) target.scrollIntoView({ behavior: 'smooth', block: 'start' });
    syncSettingsNav(id);
  });
});

document.getElementById('themeToggle').addEventListener('click', function () {
  var next = root.dataset.theme === 'dark' ? 'light' : 'dark';
  applyTheme(next);
  showToast(next === 'dark' ? '已切换到深色主题' : '已切换到浅色主题');
});

document.querySelectorAll('[data-theme-choice]').forEach(function (btn) {
  btn.addEventListener('click', function () {
    applyTheme(btn.getAttribute('data-theme-choice'));
  });
});
syncThemeControls();

document.querySelectorAll('.settings-section .seg').forEach(function (seg) {
  seg.querySelectorAll('button').forEach(function (btn) {
    if (btn.hasAttribute('data-theme-choice')) return;
    btn.addEventListener('click', function () {
      seg.querySelectorAll('button').forEach(function (b) { b.classList.remove('is-active'); });
      btn.classList.add('is-active');
    });
