document.querySelectorAll('[data-cap-switch]').forEach(function (btn) {
  btn.addEventListener('click', function () {
    var on = btn.classList.toggle('is-on');
    btn.setAttribute('aria-checked', String(on));
    var label = btn.getAttribute('aria-label') || '';
    btn.setAttribute('aria-label', (on ? '停用' : '启用') + label.replace(/^(停用|启用)/, ''));
    showToast(on ? '已启用' : '已停用');
  });
});

/* ---------- sidebar sessions ---------- */
var sessions = Array.prototype.slice.call(document.querySelectorAll('.session'));

sessions.forEach(function (item) {
  var row = document.createElement('div');
  row.className = 'session-row';
  item.parentNode.insertBefore(row, item);
  row.appendChild(item);

  var more = document.createElement('button');
  more.type = 'button';
  more.className = 'session-more';
  more.title = '会话操作';
  more.setAttribute('aria-label', '会话操作');
  more.setAttribute('aria-haspopup', 'menu');
  more.setAttribute('aria-expanded', 'false');
  more.innerHTML = '<svg class="ic" aria-hidden="true"><use href="#i-more"/></svg>';
  row.appendChild(more);

  more.addEventListener('click', function (event) {
    event.stopPropagation();
    openSessionMenu(row, more);
  });
  row.addEventListener('contextmenu', function (event) {
    event.preventDefault();
    openSessionMenu(row, null, event.clientX, event.clientY);
  });
});

function openSessionMenu(row, anchor, x, y) {
  if (sessionMenu.classList.contains('is-open') && sessionMenuTarget === row) {
    closeSessionMenu();
    return;
  }
  setAccountMenu(false);
  if (sessionMenuAnchor) sessionMenuAnchor.setAttribute('aria-expanded', 'false');
  sessionMenuTarget = row;
  sessionMenuAnchor = anchor || null;
  if (sessionMenuAnchor) sessionMenuAnchor.setAttribute('aria-expanded', 'true');

  var left, top;
  if (typeof x === 'number' && typeof y === 'number') {
    left = x; top = y;
  } else {
    var rect = anchor.getBoundingClientRect();
    left = rect.right - 176;
    top = rect.bottom + 4;
  }
  left = Math.min(Math.max(8, left), window.innerWidth - 184);
  top = Math.min(Math.max(8, top), window.innerHeight - 132);
  sessionMenu.style.left = left + 'px';
  sessionMenu.style.top = top + 'px';
  sessionMenu.classList.add('is-open');
  var first = sessionMenu.querySelector('.menu-item');
  if (first) first.focus();
}

function closeSessionMenu() {
  sessionMenu.classList.remove('is-open');
  if (sessionMenuAnchor) {
    sessionMenuAnchor.setAttribute('aria-expanded', 'false');
    sessionMenuAnchor = null;
  }
  sessionMenuTarget = null;
}

function startRename(row) {
  var btn = row.querySelector('.session');
  var title = row.querySelector('.session-title');
  var more = row.querySelector('.session-more');
  if (!btn || !title || !more) return;
  var old = title.textContent;
  var input = document.createElement('input');
  input.type = 'text';
  input.className = 'session-rename';
  input.value = old;
  input.setAttribute('aria-label', '重命名会话');
  row.classList.add('is-renaming');
  row.appendChild(input);
  input.focus();
  input.select();
  var done = false;
  function finish(save) {
    if (done) return;
    done = true;
    var next = input.value.trim();
    if (!save || !next) next = old;
    title.textContent = next;
    row.classList.remove('is-renaming');
    input.remove();
    row.insertBefore(btn, more);
    if (save && next !== old) showToast('会话已重命名');
  }
  input.addEventListener('keydown', function (event) {
    if (event.key === 'Enter') { event.preventDefault(); finish(true); }
    if (event.key === 'Escape') { event.preventDefault(); finish(false); }
  });
  input.addEventListener('blur', function () { finish(true); });
}

function archiveSession(row) {
  row.classList.add('is-archived');
  showToast('会话已归档（原型）');
}

function openDeleteDialog(row) {
  deleteSessionTarget = row;
  var title = row.querySelector('.session-title');
  deleteSessionName.textContent = title ? title.textContent : '';
  deleteDialog.classList.add('is-open');
  var dialog = deleteDialog.querySelector('.dialog');
  if (dialog) dialog.focus();
}

function closeDeleteDialog() {
  deleteDialog.classList.remove('is-open');
  deleteSessionTarget = null;
}

sessionMenu.querySelectorAll('[data-session-action]').forEach(function (btn) {
  btn.addEventListener('click', function () {
    var action = btn.getAttribute('data-session-action');
    var row = sessionMenuTarget;
    closeSessionMenu();
    if (!row) return;
    if (action === 'rename') startRename(row);
    if (action === 'archive') archiveSession(row);
    if (action === 'delete') openDeleteDialog(row);
  });
});

deleteDialog.addEventListener('click', function (event) {
  if (event.target === deleteDialog) closeDeleteDialog();
});
cancelDelete.addEventListener('click', closeDeleteDialog);
confirmDelete.addEventListener('click', function () {
  var row = deleteSessionTarget;
  if (!row) { closeDeleteDialog(); return; }
  var session = row.querySelector('.session');
  var wasActive = session && session.classList.contains('is-active');
  row.remove();
  closeDeleteDialog();
  var remaining = Array.prototype.slice.call(document.querySelectorAll('.session'));
  if (wasActive && remaining.length) {
    remaining[0].classList.add('is-active');
    remaining[0].setAttribute('aria-current', 'page');
  }
  sessionCount.textContent = String(remaining.length);
  document.querySelectorAll('.session-group').forEach(function (group) {
    group.hidden = !group.querySelector('.session');
  });
  showToast('会话已删除');
});

document.addEventListener('click', function (event) {
  if (!sessionMenu.contains(event.target)) closeSessionMenu();
});
document.addEventListener('scroll', function () { closeSessionMenu(); }, true);
document.addEventListener('keydown', function (event) {
  if (event.key === 'Escape') {
    closeSessionMenu();
    closeDeleteDialog();
  }
});

var sessionSearch = document.getElementById('sessionSearch');
if (sessionSearch) {
  sessionSearch.addEventListener('input', function () {
    var q = sessionSearch.value.trim().toLowerCase();
    var allSessions = Array.prototype.slice.call(document.querySelectorAll('.session'));
    allSessions.forEach(function (item) {
      var title = item.querySelector('.session-title').textContent.toLowerCase();
      var match = q === '' || title.indexOf(q) !== -1;
      item.hidden = !match;
      var row = item.closest('.session-row');
      if (row) row.hidden = !match;
    });
    document.querySelectorAll('.session-group').forEach(function (group) {
      var visible = Array.prototype.some.call(group.querySelectorAll('.session'), function (s) {
        return !s.hidden;
      });
      group.hidden = !visible;
    });
  });
}

document.querySelectorAll('.session').forEach(function (item) {
  item.addEventListener('click', function () { window.location.href = 'ui-v7.html'; });
});
var newSession = document.getElementById('newSession');
if (newSession) newSession.addEventListener('click', function () { window.location.href = 'ui-v7.html'; });

/* ---------- agents ---------- */
var confirmDialog = document.getElementById('confirmDialog');
var confirmTitle = document.getElementById('confirmTitle');
var confirmText = document.getElementById('confirmText');
var confirmAction = document.getElementById('confirmAction');
var cancelConfirm = document.getElementById('cancelConfirm');
var pendingConfirm = null;
var confirmReturnFocus = null;

function openConfirm(title, text, action, label) {
  pendingConfirm = action;
  confirmReturnFocus = document.activeElement;
  confirmTitle.textContent = title;
  confirmText.textContent = text;
  confirmAction.textContent = label || '确认';
  confirmDialog.classList.add('is-open');
  var dialog = confirmDialog.querySelector('.dialog');
  if (dialog) dialog.focus();
}

function closeConfirm() {
  confirmDialog.classList.remove('is-open');
  var target = confirmReturnFocus;
  pendingConfirm = null;
  confirmReturnFocus = null;
  if (target && document.contains(target) && typeof target.focus === 'function') {
    target.focus();
  }
}

confirmAction.addEventListener('click', function () {
  var action = pendingConfirm;
  closeConfirm();
  if (action) action();
});
cancelConfirm.addEventListener('click', closeConfirm);
confirmDialog.addEventListener('click', function (event) {
  if (event.target === confirmDialog) closeConfirm();
});
document.addEventListener('keydown', function (event) {
  if (event.key === 'Escape' && confirmDialog.classList.contains('is-open')) {
    event.stopImmediatePropagation();
    closeConfirm();
  }
});

var agentFilter = 'all';
var agentQuery = '';

function agentCards() {
  return Array.prototype.slice.call(document.querySelectorAll('.agent-card'));
}

function filterAgents() {
  var visible = 0;
  agentCards().forEach(function (item) {
    var health = item.getAttribute('data-health');
    var disabled = item.classList.contains('is-disabled');
    var text = item.textContent.toLowerCase();
    var matchesFilter = agentFilter === 'all' ||
      (agentFilter === 'disabled' ? disabled : (!disabled && health === agentFilter));
    var match = matchesFilter && (agentQuery === '' || text.indexOf(agentQuery) !== -1);
    item.hidden = !match;
    if (match) visible += 1;
  });
  var empty = document.getElementById('agentEmpty');
  if (empty) empty.hidden = visible > 0;
}

function updateAgentStats() {
  var cards = agentCards();
  var enabled = cards.filter(function (card) { return !card.classList.contains('is-disabled'); });
  var healthy = enabled.filter(function (card) { return card.getAttribute('data-health') === 'healthy'; }).length;
  var degraded = enabled.filter(function (card) { return card.getAttribute('data-health') === 'degraded'; }).length;
  var disabled = cards.length - enabled.length;
  var set = function (id, value) {
    var el = document.getElementById(id);
    if (el) el.textContent = String(value);
  };
  set('agentTotalStat', cards.length);
  set('agentHealthyStat', healthy);
  set('agentDegradedStat', degraded);
  set('agentEnabledStat', enabled.length);
  var allCount = document.querySelector('[data-agent-filter="all"] span');
  var healthyCount = document.querySelector('[data-agent-filter="healthy"] span');
  var degradedCount = document.querySelector('[data-agent-filter="degraded"] span');
  var disabledCount = document.querySelector('[data-agent-filter="disabled"] span');
  if (allCount) allCount.textContent = String(cards.length);
  if (healthyCount) healthyCount.textContent = String(healthy);
  if (degradedCount) degradedCount.textContent = String(degraded);
  if (disabledCount) disabledCount.textContent = String(disabled);
}

document.querySelectorAll('[data-agent-filter]').forEach(function (btn) {
  btn.addEventListener('click', function () {
    agentFilter = btn.getAttribute('data-agent-filter');
    document.querySelectorAll('[data-agent-filter]').forEach(function (b) {
      b.classList.toggle('is-active', b === btn);
    });
    filterAgents();
  });
});

var agentSearch = document.getElementById('agentSearch');
if (agentSearch) {
  agentSearch.addEventListener('input', function () {
    agentQuery = agentSearch.value.trim().toLowerCase();
    filterAgents();
  });
}

document.querySelectorAll('[data-agent-switch]').forEach(function (btn) {
  btn.addEventListener('click', function () {
    var card = btn.closest('.agent-card');
    if (!card) return;
    var enabled = btn.classList.toggle('is-on');
    btn.setAttribute('aria-checked', String(enabled));
    var nameEl = card.querySelector('.agent-name');
    var name = nameEl ? nameEl.textContent : '智能体';
    btn.setAttribute('aria-label', (enabled ? '停用 ' : '启用 ') + name);
    var label = card.querySelector('.agent-switch-label');
