var menuRows = document.getElementById('menuRows');
var menuSearch = document.getElementById('menuSearch');
var menuTypeFilter = document.getElementById('menuTypeFilter');
var menuCount = document.getElementById('menuCount');
var menuCollapseAll = document.getElementById('menuCollapseAll');
var newMenuBtn = document.getElementById('newMenuBtn');

var menuQuery = '';
var menuType = 'all';
var collapsedTrees = {};

function menuRowById(id) {
  return Array.prototype.find.call(menuRows.querySelectorAll('tr[data-menu-id]'), function (row) {
    return row.getAttribute('data-menu-id') === id;
  });
}

function menuMatches(row) {
  var typeOk = menuType === 'all' || row.getAttribute('data-type') === menuType;
  var text = (row.textContent || '').toLowerCase();
  var qOk = !menuQuery || text.indexOf(menuQuery) !== -1;
  return typeOk && qOk;
}

function menuAncestorCollapsed(row) {
  var parent = row.getAttribute('data-parent');
  while (parent) {
    if (collapsedTrees[parent]) return true;
    var parentRow = menuRowById(parent);
    parent = parentRow ? parentRow.getAttribute('data-parent') : '';
  }
  return false;
}

function applyMenuVisibility() {
  var rows = Array.prototype.slice.call(menuRows.querySelectorAll('tr[data-menu-id]'));
  var visible = {};
  rows.forEach(function (row) {
    visible[row.getAttribute('data-menu-id')] = menuMatches(row);
  });
  for (var pass = 0; pass < 5; pass += 1) {
    rows.forEach(function (row) {
      var id = row.getAttribute('data-menu-id');
      if (!visible[id]) return;
      var parent = row.getAttribute('data-parent');
      if (parent) visible[parent] = true;
    });
  }
  var count = 0;
  rows.forEach(function (row) {
    var id = row.getAttribute('data-menu-id');
    var show = !!visible[id] && !menuAncestorCollapsed(row);
    row.hidden = !show;
    if (show && menuMatches(row)) count += 1;
  });
  menuRows.querySelectorAll('[data-tree]').forEach(function (btn) {
    var id = btn.getAttribute('data-tree');
    var open = !collapsedTrees[id];
    btn.classList.toggle('is-open', open);
    btn.setAttribute('aria-expanded', String(open));
  });
  menuCount.textContent = count + ' 项';
  var anyOpen = Array.prototype.some.call(menuRows.querySelectorAll('[data-tree]'), function (btn) {
    return !collapsedTrees[btn.getAttribute('data-tree')];
  });
  menuCollapseAll.textContent = anyOpen ? '全部折叠' : '全部展开';
}

menuSearch.addEventListener('input', function () {
  menuQuery = menuSearch.value.trim().toLowerCase();
  if (menuQuery) collapsedTrees = {};
  applyMenuVisibility();
});

menuTypeFilter.addEventListener('click', function (event) {
  var btn = event.target.closest('[data-type]');
  if (!btn) return;
  menuType = btn.getAttribute('data-type');
  menuTypeFilter.querySelectorAll('button').forEach(function (b) {
    b.classList.toggle('is-active', b === btn);
  });
  collapsedTrees = {};
  applyMenuVisibility();
});

menuRows.addEventListener('click', function (event) {
  var toggle = event.target.closest('[data-tree]');
  if (toggle) {
    var id = toggle.getAttribute('data-tree');
    collapsedTrees[id] = !collapsedTrees[id];
    applyMenuVisibility();
    return;
  }
  var edit = event.target.closest('[data-menu-edit]');
  if (edit) {
    var editRow = edit.closest('tr');
    openMenuDrawer(editRow, null);
    return;
  }
  var add = event.target.closest('[data-menu-add]');
  if (add) {
    var parentRow = add.closest('tr');
    openMenuDrawer(null, parentRow.getAttribute('data-menu-id'));
    return;
  }
  var del = event.target.closest('[data-menu-delete]');
  if (del) {
    showToast('菜单项已删除（原型演示）');
  }
});

menuCollapseAll.addEventListener('click', function () {
  var trees = menuRows.querySelectorAll('[data-tree]');
  var anyOpen = Array.prototype.some.call(trees, function (btn) {
    return !collapsedTrees[btn.getAttribute('data-tree')];
  });
  Array.prototype.forEach.call(trees, function (btn) {
    var id = btn.getAttribute('data-tree');
    if (anyOpen) collapsedTrees[id] = true;
    else delete collapsedTrees[id];
  });
  applyMenuVisibility();
});

