function renderComposerContext() {
  var html = '';
  var count = 0;

  if (selectedWorkflow) {
    var wf = CHAT_WORKFLOWS[selectedWorkflow];
    html += '<span class="ctx-chip ctx-workflow">' +
      '<svg class="ic" aria-hidden="true"><use href="#i-workflow"/></svg>' +
