      '<button class="ctx-remove" data-remove="workflow" aria-label="移除工作流"><svg class="ic" aria-hidden="true"><use href="#i-x"/></svg></button>' +
    '</span>';
    count += 1;
  }

  selectedSkills.forEach(function (id) {
    html += '<span class="ctx-chip ctx-skill">' +
      '<svg class="ic" aria-hidden="true"><use href="#i-stack"/></svg>' +
      escComposer(id) +
