    '</span>';
    count += 1;
  });

  if (knowledgeSelected) {
    html += '<span class="ctx-chip ctx-knowledge">' +
      '<svg class="ic" aria-hidden="true"><use href="#i-db"/></svg>' +
      'support-kb' +
      '<button class="ctx-remove" data-remove="knowledge" aria-label="移除知识库"><svg class="ic" aria-hidden="true"><use href="#i-x"/></svg></button>' +
    '</span>';
    count += 1;
  }

  selectedMcp.forEach(function (id) {
    html += '<span class="ctx-chip ctx-mcp">' +
      '<svg class="ic" aria-hidden="true"><use href="#i-stack"/></svg>' +
      escComposer(id) +
