    workflowPreview.hidden = true;
    workflowPreviewName.textContent = '';
    workflowPreviewSteps.textContent = '';
  }

  updateComposerMenuState();
}

function selectWorkflow(id, announce) {
  var wf = CHAT_WORKFLOWS[id];
  if (!wf || wf.disabled) return;
  var hadManual = selectedSkills.length > 0 || selectedMcp.length > 0 || knowledgeSelected;
  selectedWorkflow = id;
  selectedSkills = [];
  selectedMcp = [];
  knowledgeSelected = false;
  renderComposerContext();
  closeComposerMenu();
  if (announce) showToast(hadManual ? '已选择工作流，并清空手动上下文' : '已选择工作流：' + wf.name);
