function selectManualContext() {
  if (!selectedWorkflow) return;
  selectedWorkflow = null;
  showToast('已改为手动上下文，工作流已取消');
}

function toggleSkill(id) {
  var index = selectedSkills.indexOf(id);
  if (index === -1 && selectedSkills.length >= 3) {
    showToast('本轮最多选择 3 个技能');
    return;
  }
  selectManualContext();
  if (index === -1) selectedSkills.push(id);
  else selectedSkills.splice(index, 1);
  renderComposerContext();
}

function toggleMcp(id) {
  var index = selectedMcp.indexOf(id);
  if (index === -1 && selectedMcp.length >= 5) {
    showToast('本轮最多选择 5 个 MCP 服务器');
    return;
  }
  selectManualContext();
  if (index === -1) selectedMcp.push(id);
  else selectedMcp.splice(index, 1);
  renderComposerContext();
}

function toggleKnowledge() {
  selectManualContext();
  knowledgeSelected = !knowledgeSelected;
  renderComposerContext();
}

